<?php if (!($data['preview'] ?? false)) { require __DIR__ . '/live/tracking.php'; return; } ?>
<?php use App\UI\UI as U;
$orderId = !isset($_GET['order']) ? 'HMT-104' : (is_string($_GET['order']) ? $_GET['order'] : '');
$order = null;
foreach ($data['sample']['orders'] as $candidate) { if ($candidate['id'] === $orderId) { $order = $candidate; break; } }
if (!$order): ?><?= U::heading('Order not found', 'Choose an order from your sample history.') ?><?= U::btn('My orders', '/customer/orders', 'primary', 'arrow-left') ?><?php return; endif;
$station = null; foreach ($data['sample']['stations'] as $candidate) { if ($candidate['id'] === $order['station_id']) { $station = $candidate; break; } }
$pickup = $order['fulfillment'] === 'pickup'; $progress = $pickup ? \App\UI\Fulfillment::pickupProgress() : $data['sample']['progress'];
if (!$pickup && $order['stage'] >= 4) { $progress[4][1] = 'Your order was delivered.'; $progress[4][2] = '10:15 AM'; }
?>
<?= U::heading('Order '.$order['id'], $pickup ? 'Track your pickup and collection details.' : 'Track your order and delivery details.', U::btn('Message station', '/customer/messages?station='.$station['id'], 'primary', 'message').U::btn('My orders', '/customer/orders', 'secondary', 'arrow-left')) ?>
<div class="grid gap-5 lg:grid-cols-2"><div class="space-y-5"><section class="panel p-5 flex items-center gap-4"><?= U::productImage('h-24 w-24 rounded-lg bg-foam') ?><div><h2 class="font-bold text-xl"><?= U::e($station['name']) ?></h2><p class="muted">Brgy. <?= U::e($station['area']) ?>, Hamtic, Antique</p><div class="mt-3"><?= U::badge($order['status'], $order['tone']) ?></div></div></section><section class="panel p-5 md:p-6"><?= U::title('Order progress','orders','') ?><p class="muted mb-5"><?= U::e($order['status']) ?>. Sample progress for <?= U::e($order['date']) ?>.</p><ol><?php foreach ($progress as $i => $step): ?><li class="relative flex gap-4 pb-6 last:pb-0"><div class="relative flex flex-col items-center"><span class="relative z-10 flex size-8 shrink-0 items-center justify-center rounded-full <?= $i <= $order['stage'] ? 'bg-water text-white' : 'bg-white border-2 border-line' ?>"><?= $i < $order['stage'] ? U::icon('check', 'size-5') : ($i === $order['stage'] ? U::icon($pickup || $order['stage'] >= 4 ? 'check' : 'truck', 'size-4') : '') ?></span><?php if ($i < count($progress) - 1): ?><span class="absolute top-8 bottom-0 w-0.5 <?= $i < $order['stage'] ? 'bg-water' : 'bg-line' ?>"></span><?php endif; ?></div><div class="flex-1"><div class="flex flex-wrap justify-between gap-2"><h3 class="font-bold"><?= U::e($step[0]) ?></h3><time class="muted text-sm"><?= U::e($step[2]) ?></time></div><p class="muted mt-1"><?= U::e($step[1]) ?></p></div></li><?php endforeach; ?></ol></section><section class="panel p-5 md:p-6"><?= U::title('Order items','orders','mb-4') ?><?= U::table(['Item', 'Quantity', 'Price', 'Total'], [[U::productImage('h-12 w-12 inline-block mr-2').U::e(\App\UI\Products::get('round')['name']), U::e($order['quantity']), U::money(\App\UI\Products::get('round')['price']), U::money($order['quantity'] * \App\UI\Products::get('round')['price'])]]) ?><?php if ($order['fulfillment'] === 'delivery'): ?><div class="flex justify-between text-sm mt-4"><span class="muted">Delivery fee</span><span><?= U::money($order['total'] - $order['quantity'] * \App\UI\Products::get('round')['price']) ?></span></div><?php endif; ?><div class="flex justify-between font-bold mt-4"><span>Total</span><span><?= U::money($order['total']) ?></span></div><div class="mt-4 bg-foam rounded-lg p-4"><span class="muted">Payment method</span><p class="font-semibold"><?= $pickup ? 'Cash on pickup' : 'Cash on delivery' ?></p></div></section></div><div class="space-y-5"><section class="panel p-5 md:p-6"><?php if ($pickup): ?><?= U::title('Pickup information','file','mb-5') ?><p class="font-bold"><?= U::e($station['name']) ?></p><p>Brgy. <?= U::e($station['area']) ?>, Hamtic, Antique</p><p class="muted mt-3">Monday-Saturday: <?= U::e($station['hours']) ?><br>Sunday: <?= U::e($station['sunday']) ?></p><p class="muted mt-3">Bring empty containers and pay at the station when collecting.</p><?php else: ?><?= U::title('Delivery information','truck','mb-5') ?><div class="flex flex-wrap items-center gap-4"><?= U::avatar('JR', 'size-16') ?><div class="flex-1"><h3 class="font-bold text-lg">Rider Juan Reyes</h3><p class="muted">HydroRoute Delivery</p><p class="muted">Sample rider contact</p></div><?= U::btn('Contact rider', '', 'secondary', 'phone', ['data-toast' => 'This fictional rider has no connected phone service.', 'data-demo-action' => true]) ?></div><div class="border-t border-line mt-6 pt-5 flex gap-3"><?= U::icon('pin', 'size-6 text-water') ?><div class="flex-1"><h3 class="font-bold">Delivery address</h3><p class="mt-1">Home</p><p class="muted">Purok 2, Guintas, Hamtic, Antique</p><div class="mt-3"><?= U::btn('View address', '/customer/addresses', 'secondary') ?></div></div></div><?php endif; ?></section><section class="rounded-xl border border-line bg-foam p-5"><h2 class="font-bold text-lg">Need help?</h2><p class="muted my-3">For questions about your order, contact <?= U::e($station['name']) ?> directly.</p><?= U::btn('View station', '/customer/station?station='.$station['id'], 'primary', 'store') ?></section><section class="rounded-xl border border-amber-200 bg-amber-50 p-5"><h2 class="font-bold text-amber-900">Cancellation unavailable</h2><p class="text-amber-800 mt-2">This sample order cannot be cancelled because it is <?= U::e(strtolower($order['status'])) ?>.</p></section><section class="panel p-5 md:p-6"><?= U::title('Order history','orders','mb-4') ?><?php $rows = []; foreach (array_slice($progress, 0, $order['stage'] + 1) as $step) $rows[] = [U::e($order['date']).' · '.U::e($step[2]), U::e($step[0]), U::e($step[1])]; echo U::table(['Date & time', 'Status', 'Notes'], $rows); ?></section></div></div>
